def count_passing_ways(n, m):
    # Initialize a 2D array to store the number of passing ways for each student and pass
    dp = [[0] * (m + 1) for _ in range(n)]

    # Base case: No passing required
    for i in range(n):
        dp[i][0] = 1

    # Populate the 2D array using dynamic programming
    for i in range(n):
        for j in range(1, m + 1):
            if i == 0:
                dp[i][j] = dp[i][j - 1] + dp[n - 1][j - 1]
            else:
                dp[i][j] = dp[i - 1][j - 1] + dp[i + 1][j - 1]

