def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Initialize a 2D table to store the results of subproblems
    dp = [[0] * (n + 1) for _ in range(V + 1)]

    # Fill in the base cases for the table
    for i in range(V + 1):
        dp[i][0] = 0
    for j in range(n + 1):
        dp[0][j] = 0

    # Iterate over the remaining rows and columns
    for i in range(1, V + 1):
        for j in range(1, n + 1):
            # If the current volume is larger than the current item, we can choose
            # to include it or not
            if i >= volumes[j - 1]:
                dp[i][j] = max(dp[i][j - 1], dp[i - volumes[j - 1]][j - 1] + volumes[j - 1])
            # Otherwise, we must exclude the current item
            else:
                dp[i][j] = dp[i][j - 1]

    # The minimum remaining space is the difference between the total capacity and
    # the maximum occupied volume
    return V - dp[V][n]
```

