    for i in range(1, V + 1):
        for j in range(1, n + 1):
            # If the current item does not fit in the box, ignore it
            if volumes[j - 1] > i:
                dp[i][j] = dp[i][j - 1]
            else:
                dp[i][j] = max(dp[i - volumes[j - 1]][j - 1], dp[i][j - 1])

