def calculate_arrangements(n, m, a):
    # Initialize the dp table
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Base case: If there are no pots to arrange, there is only one arrangement
    dp[0][0] = 1

    # Populate the dp table
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            # If the ith type of flower is not available,
            # then the number of arrangements is the same as the previous type
            if a[i - 1] == 0:
                dp[i][j] = dp[i - 1][j]
            # Otherwise, consider all combinations of using the ith type of flower
            else:
                for k in range(min(a[i - 1], j) + 1):
                    dp[i][j] += dp[i - 1][j - k]

    # Return the number of arrangements modulo (10^6 + 7)
    return dp[n][m] % (10**6 + 7)
