def calculate_arrangements(n, m, a):
    # Initialize a 2D array to store the results
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Base case: when m = 0, there is only one arrangement (empty)
    for i in range(n + 1):
        dp[i][0] = 1

    # Populate the table
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            # Case 1: choose the ith type with one pot
            dp[i][j] += dp[i - 1][j - 1]
            # Case 2: choose the ith type with more than one pot
            if j >= a[i - 1]:
                dp[i][j] += dp[i][j - a[i - 1]]

    # Return the result
    return dp[n][m] % (10**6 + 7)
